#include <stdlib.h>
#include "token.h"
*/
import "C"
import (
  "fmt"
  "unsafe"
)

func GenerateToken(prefix string) (string, error) {
  buf := make([]C.char, 256)
  cPrefix := C.CString(prefix)
  defer C.free(unsafe.Pointer(cPrefix))
  var err C.int
